const upsertHelpCollectionTranslation = `-- name: UpsertHelpCollectionTranslation :exec
INSERT INTO help_collection_translations (workspace_id, collection_id, locale, name, description, slug, updated_at)
VALUES ($1, $2, $3, $4, $5, $6, $7)
ON CONFLICT (workspace_id, collection_id, locale) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description, slug = EXCLUDED.slug, updated_at = EXCLUDED.updated_at
`

type UpsertHelpCollectionTranslationParams struct {
	WorkspaceID  uuid.UUID
	CollectionID uuid.UUID
	Locale       string
	Name         string
	Description  string
	Slug         string
	Now          time.Time
}

func (q *Queries) UpsertHelpCollectionTranslation(ctx context.Context, arg UpsertHelpCollectionTranslationParams) error {
	_, err := q.db.Exec(ctx, upsertHelpCollectionTranslation,
		arg.WorkspaceID,
		arg.CollectionID,
		arg.Locale,
		arg.Name,
		arg.Description,
		arg.Slug,
		arg.Now,
	)
	return err
}
